findings.suggestion:
删除硬编码默认口令，缺失或过弱时直接失败并明确报错：
def get_admin_password(config):
    try:
        pwd = config["admin_password"]
    except KeyError:
        raise ConfigError("必须显式配置 admin_password，禁止使用默认口令") from None
    if not pwd or len(pwd) < 12:
        raise ConfigError("admin_password 过弱")
    return pwd
若确实需要开发默认值，应只在显式开启的 dev 模式且启动时打印告警的情况下使用。

按异常类型分别处理并显式暴露问题，默认值回退由调用方显式选择：
def read_source(name, default=None):
    path = _resolve(name)
    try:
        with open(path, encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError:
        logger.error("配置文件不存在: %s", path)
    except PermissionError:
        logger.error("配置文件不可读: %s", path)
    except json.JSONDecodeError as exc:
        logger.error("配置文件解析失败: %s (%s)", path, exc)
    except OSError as exc:
        logger.error("读取配置失败: %s (%s)", path, exc)
    if default is None:
        raise ConfigError("读取配置 %s 失败" % name)
    return copy.deepcopy(default)

