findings.suggestion:
按声明做校验与显式转换，失败时指出键名，并显式处理未知键：
def coerce(config):
    result = {}
    for key, typ in EXPECTED_TYPES.items():
        if key not in config:
            continue
        value = config[key]
        if typ is bool and isinstance(value, str):
            value = value.strip().lower() in ("1", "true", "yes", "on")
        elif typ is not bool and not isinstance(value, typ):
            try:
                value = typ(value)
            except (TypeError, ValueError):
                raise ConfigError("配置 %s 期望 %s，实际 %r" % (key, typ.__name__, value)) from None
        result[key] = value
    unknown = set(config) - set(EXPECTED_TYPES)
    if unknown:
        logger.warning("忽略未知配置键: %s", sorted(unknown))
    return result

